def main():
    n = int(sys.stdin.read().split()[0])
    if n < 2:
        print('NO')
        return
    if n < 4:
        print('YES')
        return
    if n % 2 == 0 or n % 3 == 0:
        print('NO')
        return
    d = 5
    while d * d <= n:
        if n % d == 0 or n % (d + 2) == 0:
            print('NO')
            return
        d += 6
    print('YES')

