def gen(rng):
    def is_prime(n):
        if n < 2:
            return False
        if n % 2 == 0:
            return n == 2
        d = 3
        while d * d <= n:
            if n % d == 0:
                return False
            d += 2
        return True
    def prime_below(x):
        while not is_prime(x):
            x -= 1
        return x
    tests = [str(v) for v in (1, 2, 3, 4, 9, 25, 49, 97, 100, 121, 7919, 1000, 1009)]
    for _ in range(12):
        tests.append(str(rng.randint(1, 3000)))
    p1 = prime_below(10**6)
    p2 = prime_below(p1 - 1)
    tests.append(str(10**12))
    tests.append(str(p1 * p1))
    tests.append(str(p1 * p2))
    tests.append(str(prime_below(10**12)))
    tests.append(str(prime_below(rng.randint(5 * 10**11, 10**12))))
    tests.append(str(2 * prime_below(5 * 10**11)))
    return tests

